from PIL import Image
img = Image.open('code.png').convert('L')
w,h = img.size
px = img.load()
rowdark = []
for y in range(h):
    s=0
    for x in range(0,w,2):
        if px[x,y]<128: s+=1
    rowdark.append(s)
# find bands where s>0
bands=[]
inband=False
for y in range(h):
    if rowdark[y]>0 and not inband:
        start=y; inband=True
    elif rowdark[y]==0 and inband:
        bands.append((start,y)); inband=False
if inband: bands.append((start,h))
print('num bands',len(bands))
for b in bands: print(b, b[1]-b[0])
